        // Otherwise ownerAfterFirst should equal ownerBefore.
        bool firstSucceededImpliesSet = (!firstReverted) ? (ownerAfterFirst == initialSet) : (ownerAfterFirst == ownerBefore);

        // Next, attempt a second transferOwnership to finalTry, catching revert.
