contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller will attempt to transfer ownership to newOwner;
    // we model two scenarios by choosing a boolean tryAsOwner: if true, the call is made by the current owner (which is this contract because it deployed c), otherwise made by an external caller simulated via a different address contract DeployerProxy.
    function run(address newOwner, bool tryAsOwner) public payable {
        require(newOwner != address(0));

        // read initial owner
        address ownerBefore = c.owner();

        // We'll need an external actor to attempt the call when tryAsOwner == false.
        // Deploy a lightweight proxy that can call c; it will be a new contract created here.
        // Define it inline via assembly-style creation: use a minimal proxy contract bytecode
        // Since we cannot declare new contracts, instead use an already allowed approach:
        // If tryAsOwner is true, this contract (which is c.owner() because test deployer constructed c) will call transferOwnership.
        // If tryAsOwner is false, attempt the call via a low-level call from this contract but change msg.sender cannot be altered — therefore we emulate a non-owner by first setting owner to this contract and then transferring ownership away so this contract is not the owner, then attempt transferOwnership which should revert.

        // Ensure owner is this contract initially: if not, try to set it by calling transferOwnership (requires onlyOwner). We cannot assume deployment set owner; but the checker deploys a fresh c and runs run() once; owner may be zero. To make predictable: if ownerBefore == address(this), we proceed. Otherwise, if ownerBefore == address(0), we cannot call onlyOwner. So we handle by checking two branches: if ownerBefore==address(this) then this contract is owner; else we cannot become owner and must assert accordingly.

        // Case A: tryAsOwner == true: require this contract is ownerBefore, then call transferOwnership (should succeed) and owner() should equal newOwner.
        if (tryAsOwner) {
            // require precondition that this test contract is the owner so the transfer should succeed
            require(ownerBefore == address(this));

            // perform ownership transfer as owner
            c.transferOwnership(newOwner);

            address ownerAfter = c.owner();
            // General rule: when called by current owner, owner changes to newOwner
            assert(ownerAfter == newOwner);
        } else {
            // Case B: tryAsOwner == false: require this contract is NOT the owner so the transfer attempt from this contract should revert and owner unchanged.
            require(ownerBefore != address(this));

            bool reverted;
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }

            address ownerAfter = c.owner();
            // General rule: non-owner calls revert and owner stays the same
            assert(reverted == true && ownerAfter == ownerBefore);
        }
    }

    receive() external payable {}
}

