contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to transfer ownership and check behavior
    function run(address newOwner, bool callAsOwner) public payable {
        require(newOwner != address(0));
        // Read initial owner
        address beforeOwner = c.owner();

        bool reverted;
        // Decide who should call transferOwnership: either this contract (the owner) or simulate non-owner
        // Since the checker deploys a fresh C with owner == msg.sender at deployment and our test contract deployed c,
        // InvMutTest is the initial owner. We model two cases:
        if (callAsOwner) {
            // call as owner (this contract)
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call as non-owner: perform a low-level call from this contract but specifying a different sender is impossible here.
            // To simulate a non-owner call, we invoke transferOwnership via address(c).call with encoded selector,
            // which still uses msg.sender = address(this) and thus would be owner; to create a non-owner caller we instead
            // call a public view to get owner and then assert that any attempt by non-owner would revert — we model this by
            // first transferring ownership away so this contract is no longer owner, then attempting transfer as non-owner.

            // transfer ownership away to newOwner so this contract is no longer owner
            try c.transferOwnership(newOwner) {
                // succeeded, now this contract is not owner
                reverted = false;
            } catch {
                // if this revert happened, we cannot proceed to test non-owner behavior; mark reverted=true
                reverted = true;
            }

            if (!reverted) {
                // now this contract is non-owner; attempt to transfer ownership again to some other address (use beforeOwner)
                // use try/catch to detect revert
                try c.transferOwnership(beforeOwner) {
                    // If this succeeded, non-owner was able to change owner
                    reverted = false;
                } catch {
                    // Expected revert for non-owner
                    reverted = true;
                }
            }
        }

        // Read owner after attempted operations
        address afterOwner = c.owner();

        // General rule asserted:
        // - If the final transfer attempt was made by the legitimate owner, then owner equals newOwner (it changed).
        // - If the final transfer attempt was made by a non-owner, the call reverted and owner did not become the attacker value.
        // We express this as: either owner changed to newOwner (when callAsOwner==true and call did not revert),
        // or owner did not change to the attacker value (when callAsOwner==false the owner is not beforeOwner unless a successful owner action occurred).

        // Formalize: if callAsOwner is true and the call did not revert, then afterOwner == newOwner.
        // If callAsOwner is false, then afterOwner != beforeOwner || reverted == false implies a legitimate owner change happened earlier,
        // but in the critical last non-owner attempt the owner must not become beforeOwner unless reverted == false and that would imply owner was allowed.

        // To keep a single clear general condition suitable for formal checking:
        // If the last attempted transfer was initiated while this contract was the owner, then afterOwner == (callAsOwner ? newOwner : afterOwner);
        // More directly: when callAsOwner is true and the final try did not revert, owner equals newOwner; when callAsOwner is false and the final try reverted, owner did not change to beforeOwner.

        if (callAsOwner) {
            // We require that if we attempted as owner then the final state reflects the change unless the call reverted.
            assert(reverted || afterOwner == newOwner);
        } else {
            // If we attempted as non-owner (after first giving ownership away), then the final attempted change must have reverted.
            // Therefore, if it reverted then owner must still be newOwner (the value we transferred away to), otherwise if it did not revert,
            // ownership changed and that indicates a violation — we assert owner is not equal to beforeOwner unless the non-owner call succeeded (which should not happen).
            // Concretely: after a non-owner attempt, either reverted == true and afterOwner == newOwner, or reverted == false implies afterOwner != beforeOwner is acceptable
            // but we assert that a non-owner attempt cannot make the owner equal to beforeOwner (i.e., revert protection holds).
            assert(reverted ? afterOwner == newOwner : afterOwner != beforeOwner);
        }
    }

    receive() external payable { }
}
